    <ol style="margin:6px 0;padding-left:22px;">
    <li>Pilgrims separated from the Church of England; Puritans sought to reform it.</li>
    <li>Puritan beliefs in the Bible, providence and covenant shaped their plain-style writing.</li>
    <li>Bradford’s Of Plymouth Plantation presents the colony’s survival as God’s providence.</li>
    <li>Winthrop’s “city upon a hill” gave colonists, and later Americans, a sense of mission.</li>
    <li>Bradstreet’s poems express personal love and loss balanced with faith.</li>
    <li>Edwards’s “Sinners” uses vivid imagery and pathos to create urgency during the Great Awakening.</li>
    </ol>
